3	/// Result of parsing a `patchedDependencies` key.
4	///
5	/// Mirrors the subset of upstream's
6	/// [`parse`](https://github.com/pnpm/pnpm/blob/b4f8f47ac2/deps/path/src/index.ts#L120-L168)
7	/// that [`groupPatchedDependencies`](https://github.com/pnpm/pnpm/blob/b4f8f47ac2/patching/config/src/groupPatchedDependencies.ts#L19-L21)
8	/// uses. Patched-dependency keys never carry peer-graph or
9	/// patch-hash suffixes, so this parser only distinguishes:
10	///
11	/// - bare `name` → both fields are `None`,
12	/// - `name@<valid-semver>` → `version` is `Some`,
13	/// - `name@<anything-else>` → `non_semver_version` is `Some`.
14	#[derive(Debug, Default, PartialEq, Eq)]
15	pub struct ParsedKey<'a> {
16	    pub name: Option<&'a str>,
17	    pub version: Option<&'a str>,
18	    pub non_semver_version: Option<&'a str>,
19	}
20	
21	/// Parse a `patchedDependencies` key.
22	///
23	/// Returns `ParsedKey::default()` (all `None`) when the input has no
24	/// `@` separator at index ≥ 1 — matching upstream where `dp.parse`
25	/// returns the empty object `{}`. Callers handle that case by treating
26	/// the entire key as a bare package name (wildcard match).
27	pub fn parse_key(input: &str) -> ParsedKey<'_> {
28	    // `indexOf('@', 1)` upstream — skip a leading `@` so scoped names
29	    // (`@scope/foo`) match on the *second* `@`.
30	    let bytes = input.as_bytes();
31	    let sep_index = bytes.iter().enumerate().skip(1).find_map(|(i, &b)| (b == b'@').then_some(i));
32	
33	    let Some(sep) = sep_index else {
34	        return ParsedKey::default();
35	    };
36	
37	    let name = &input[..sep];
38	    let version = &input[sep + 1..];
39	    if version.is_empty() {
40	        return ParsedKey::default();
41	    }
42	
43	    if Version::parse(version).is_ok() {
44	        ParsedKey { name: Some(name), version: Some(version), non_semver_version: None }
45	    } else {
46	        ParsedKey { name: Some(name), version: None, non_semver_version: Some(version) }
47	    }
48	}
