60	    #[test]
61	    fn bare_scoped_name_returns_empty() {
62	        // `@scope/foo` has `@` at index 0; `indexOf('@', 1)` upstream
63	        // skips it, and there is no second `@`. Falls into the
64	        // wildcard bucket.
65	        assert_eq!(parse_key("@scope/foo"), ParsedKey::default());
66	    }
67	
68	    #[test]
69	    fn name_at_exact_version() {
70	        assert_eq!(
71	            parse_key("lodash@4.17.21"),
72	            ParsedKey { name: Some("lodash"), version: Some("4.17.21"), non_semver_version: None },
73	        );
74	    }
75	
76	    #[test]
77	    fn scoped_name_at_exact_version() {
78	        assert_eq!(
79	            parse_key("@scope/foo@1.0.0"),
80	            ParsedKey {
81	                name: Some("@scope/foo"),
82	                version: Some("1.0.0"),
