105	    /// `1.x.x` is a valid semver *range* but not a valid semver
106	    /// *version*. Upstream's `semver.valid()` returns null, so the
107	    /// parsed result lands in `nonSemverVersion`.
108	    #[test]
109	    fn version_with_x_is_range() {
