    pub direct: Vec<DirectDep>,
    pub packages: HashMap<String, ResolvedPackage>,
    pub dependencies_tree: DependenciesTree,
    pub all_peer_dep_names: HashSet<String>,
    pub policy_violations: Vec<ResolutionPolicyViolation>,
